import{loadContext,formatMoney,saleSalary,salePlanSalary,saleRevenue,saleDate,startOfMonth,endOfMonth,inDateRange,initPageState,applyTheme,enableDialogBackdropClose,showFatal,escapeHtml}from"./core.js";
const $=id=>document.getElementById(id);let ctx,selected=startOfMonth(new Date());
const monthValue=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
function monthRows(offset=0){const d=new Date(selected);d.setMonth(d.getMonth()+offset);return ctx.sales.filter(s=>inDateRange(s,startOfMonth(d),endOfMonth(d)))}
function active(rows){return rows.filter(s=>!s.returned)}
function totals(rows){return active(rows).reduce((a,s)=>{a.salary+=saleSalary(s);a.planSalary+=salePlanSalary(s);a.revenue+=saleRevenue(s);a.qty+=Number(s.quantity);a.operations++;return a},{salary:0,planSalary:0,revenue:0,qty:0,operations:0})}
function render(){const all=monthRows(),rows=active(all),t=totals(all),prev=totals(monthRows(-1));$("periodTitle").textContent=selected.toLocaleDateString("ru-RU",{month:"long",year:"numeric"});$("monthPicker").value=monthValue(selected);$("monthPicker").max=monthValue(new Date());$("salaryTotal").textContent=formatMoney(t.salary);$("planSalaryTotal").textContent=formatMoney(t.planSalary);$("planDifference").textContent=`Дополнительно ${formatMoney(Math.max(0,t.planSalary-t.salary))}`;$("revenueTotal").textContent=formatMoney(t.revenue);$("quantityTotal").textContent=t.qty;$("averageSalary").textContent=formatMoney(t.qty?t.salary/t.qty:0);$("operationsTotal").textContent=t.operations;$("averageSale").textContent=formatMoney(t.operations?t.revenue/t.operations:0);$("returnsTotal").textContent=all.filter(s=>s.returned).length;$("largestSalary").textContent=formatMoney(Math.max(0,...rows.map(saleSalary)));$("monthComparison").textContent=prev.salary?`${t.salary>=prev.salary?"↑":"↓"} ${Math.abs(Math.round((t.salary-prev.salary)/prev.salary*100))}% к прошлому месяцу`:"Нет данных для сравнения";const daily=new Map;for(const s of rows){const k=saleDate(s).getDate();daily.set(k,(daily.get(k)||0)+saleSalary(s))}const max=Math.max(1,...daily.values()),days=new Date(selected.getFullYear(),selected.getMonth()+1,0).getDate();$("dailyChart").innerHTML=Array.from({length:days},(_,i)=>`<i class="bar" title="${i+1}: ${formatMoney(daily.get(i+1)||0)}" style="height:${Math.max(2,(daily.get(i+1)||0)/max*100)}%"></i>`).join("");const best=[...daily].sort((a,b)=>b[1]-a[1])[0];$("bestDay").textContent=best?`${best[0]} число · ${formatMoney(best[1])}`:"—";const cats=new Map;for(const s of rows)cats.set(s.category||"Без категории",(cats.get(s.category||"Без категории")||0)+saleSalary(s));const top=[...cats].sort((a,b)=>b[1]-a[1]).slice(0,6),catMax=Math.max(1,...top.map(x=>x[1]));$("categoryAnalytics").innerHTML=top.length?top.map(([n,v])=>`<div class="category-row"><span>${escapeHtml(n)}</span><b>${formatMoney(v)}</b><div class="progress"><i style="width:${v/catMax*100}%"></i></div></div>`).join(""):'<div class="empty">Нет данных</div>';$("nextMonth").disabled=selected>=startOfMonth(new Date())}
function setThemeControlValues(){const raw=Number(localStorage.getItem("seb-theme-hue")),hue=Number.isFinite(raw)&&raw>=0&&raw<=360?Math.round(raw):216,size=localStorage.getItem("seb-theme-size")||"medium",atmosphere=localStorage.getItem("seb-theme-atmosphere")||"aurora",surface=localStorage.getItem("seb-theme-surface")||"solid";$("darkTheme").checked=localStorage.getItem("seb-theme-dark")!=="0";$("accentPicker").value=String(hue);$("accentOrb").style.background=`hsl(${hue} 100% 59%)`;$("accentValue").textContent=`${hue}°`;document.querySelectorAll("[data-size]").forEach(x=>x.classList.toggle("active",x.dataset.size===size));document.querySelectorAll("[data-atmosphere]").forEach(x=>x.classList.toggle("active",x.dataset.atmosphere===atmosphere));document.querySelectorAll("[data-surface]").forEach(x=>x.classList.toggle("active",x.dataset.surface===surface))}
function saveTheme(key,value){localStorage.setItem(key,value);applyTheme();setThemeControlValues()}
async function init(){initPageState("overview",()=>({month:selected.toISOString()}),s=>{if(s.month)selected=startOfMonth(new Date(s.month))});ctx=await loadContext();render();$("prevMonth").onclick=()=>{selected.setMonth(selected.getMonth()-1);render()};$("nextMonth").onclick=()=>{if(selected>=startOfMonth(new Date()))return;selected.setMonth(selected.getMonth()+1);render()};$("monthPicker").onchange=e=>{if(!e.target.value)return;const[y,m]=e.target.value.split("-").map(Number);selected=new Date(y,m-1,1);render()};$("themeButton").onclick=()=>{$("themeDialog").showModal();setThemeControlValues()};const picker=$("accentPicker"),wrap=document.querySelector(".color-spectrum");picker.type="range";picker.min="0";picker.max="360";picker.step="1";picker.className="theme-range";picker.disabled=false;wrap.className="theme-hue-control";wrap.previousElementSibling.querySelector("small").textContent="Передвиньте ползунок по спектру";setThemeControlValues();$("darkTheme").onchange=e=>saveTheme("seb-theme-dark",e.target.checked?"1":"0");picker.oninput=e=>saveTheme("seb-theme-hue",e.target.value);$("sizeChoices").onclick=e=>{const b=e.target.closest("[data-size]");if(b)saveTheme("seb-theme-size",b.dataset.size)};$("atmosphereChoices").onclick=e=>{const b=e.target.closest("[data-atmosphere]");if(b)saveTheme("seb-theme-atmosphere",b.dataset.atmosphere)};$("surfaceChoices").onclick=e=>{const b=e.target.closest("[data-surface]");if(b)saveTheme("seb-theme-surface",b.dataset.surface)};$("resetTheme").onclick=()=>{["seb-theme-dark","seb-theme-accent","seb-theme-hue","seb-theme-size","seb-theme-atmosphere","seb-theme-surface","seb-theme-density","seb-theme-radius","seb-theme-scale","seb-theme-contrast"].forEach(k=>localStorage.removeItem(k));applyTheme();setThemeControlValues()}}
enableDialogBackdropClose($("themeDialog"));init().catch(showFatal);
